    "innerHTML": "<div style=\"position: absolute; inset: 0px; background: rgb(240, 246, 255);\">\n  <!-- \u9876\u680f -->\n  <div style=\"position:absolute;left:0;top:0;width:960px;height:56px;background:#0d2b6b;display:flex;align-items:center;padding:0 32px;box-sizing:border-box;\">\n    <span style=\"color:#ffffff;font-size:13px;letter-spacing:2px;opacity:0.85;\">ALGORITHM</span>\n    <span style=\"color:#ffffff;font-size:15px;font-weight:700;margin-left:auto;\">DQN \u7b97\u6cd5\u539f\u7406</span>\n  </div>\n\n  <!-- \u5de6\u5217\uff1a\u516c\u5f0f\u5361\u7247 -->\n  <!-- Bellman \u6700\u4f18\u65b9\u7a0b -->\n  <div style=\"position:absolute;left:32px;top:72px;width:440px;background:#fff;border-radius:10px;padding:14px 18px;border-left:4px solid #1a56db;box-shadow:0 2px 8px rgba(26,86,219,0.08);\">\n    <div style=\"font-size:12px;color:#1a56db;font-weight:700;margin-bottom:6px;\">Bellman \u6700\u4f18\u65b9\u7a0b</div>\n    <div style=\"font-size:13px;color:#1e293b;font-family:'Times New Roman',serif;\">Q*(s,a) = E[r + \u03b3 \u00b7 max<sub>a'</sub> Q*(s', a')]</div>\n  </div>\n\n  <!-- DQN \u635f\u5931\u51fd\u6570 -->\n  <div style=\"position:absolute;left:32px;top:158px;width:440px;background:#fff;border-radius:10px;padding:14px 18px;border-left:4px solid #7c3aed;box-shadow:0 2px 8px rgba(124,58,237,0.08);\">\n    <div style=\"font-size:12px;color:#7c3aed;font-weight:700;margin-bottom:6px;\">DQN \u635f\u5931\u51fd\u6570</div>\n    <div style=\"font-size:13px;color:#1e293b;font-family:'Times New Roman',serif;\">L(\u03b8) = E[(y<sub>t</sub> \u2212 Q(s,a;\u03b8))\u00b2]</div>\n  </div>\n\n  <!-- TD \u76ee\u6807 -->\n  <div style=\"position:absolute;left:32px;top:244px;width:440px;background:#fff;border-radius:10px;padding:14px 18px;border-left:4px solid #0891b2;box-shadow:0 2px 8px rgba(8,145,178,0.08);\">\n    <div style=\"font-size:12px;color:#0891b2;font-weight:700;margin-bottom:6px;\">TD \u76ee\u6807\uff08Target Network\uff09</div>\n    <div style=\"font-size:13px;color:#1e293b;font-family:'Times New Roman',serif;\">y<sub>t</sub> = r<sub>t</sub> + \u03b3 \u00b7 max<sub>a'</sub> Q(s<sub>t+1</sub>, a'; \u03b8\u207b)</div>\n  </div>\n\n  <!-- Q-Learning \u66f4\u65b0\u89c4\u5219 -->\n  <div style=\"position:absolute;left:32px;top:330px;width:440px;background:#fff;border-radius:10px;padding:14px 18px;border-left:4px solid #059669;box-shadow:0 2px 8px rgba(5,150,105,0.08);\">\n    <div style=\"font-size:12px;color:#059669;font-weight:700;margin-bottom:6px;\">Q-Learning \u66f4\u65b0\u89c4\u5219</div>\n    <div style=\"font-size:13px;color:#1e293b;font-family:'Times New Roman',serif;\">Q(s,a) \u2190 Q(s,a) + \u03b1[r + \u03b3\u00b7max<sub>a'</sub>Q(s',a') \u2212 Q(s,a)]</div>\n  </div>\n\n  <!-- \u03b5-greedy \u7b56\u7565 -->\n  <div style=\"position:absolute;left:32px;top:416px;width:440px;background:#fff;border-radius:10px;padding:14px 18px;border-left:4px solid #d97706;box-shadow:0 2px 8px rgba(217,119,6,0.08);\">\n    <div style=\"font-size:12px;color:#d97706;font-weight:700;margin-bottom:6px;\">\u03b5-greedy \u63a2\u7d22\u7b56\u7565</div>\n    <div style=\"font-size:13px;color:#1e293b;font-family:'Times New Roman',serif;\">a = argmax<sub>a</sub> Q(s,a;\u03b8)\u3000(prob 1\u2212\u03b5)<br>a = random\u3000(prob \u03b5)</div>\n  </div>\n\n  <!-- \u53f3\u5217\uff1aDQN\u8bad\u7ec3\u6d41\u7a0b\u56fe -->\n  <div style=\"position:absolute;left:500px;top:72px;width:428px;height:440px;background:#fff;border-radius:10px;padding:12px;box-shadow:0 2px 8px rgba(0,0,0,0.06);display:flex;flex-direction:column;align-items:center;\">\n    <div style=\"font-size:12px;color:#0d2b6b;font-weight:700;margin-bottom:8px;\">DQN \u8bad\u7ec3\u6d41\u7a0b</div>\n    <img src=\"/images/dqn_training_flow.png\" style=\"width:100%;height:auto;border-radius:6px;object-fit:contain;max-height:400px;\" alt=\"DQN Training Flow\">\n  </div>\n\n  <!-- \u5e95\u680f -->\n  <div style=\"position:absolute;left:32px;bottom:8px;width:896px;display:flex;justify-content:space-between;\">\n    <span style=\"color:#0d2b6b;font-size:11px;opacity:0.6;\">DQN on CartPole-v1 &nbsp;|&nbsp; \u5434\u5bd2\u96e8 &nbsp;2352885</span>\n    <span style=\"color:#0d2b6b;font-size:11px;opacity:0.6;\">04 / 13</span>\n  </div>\n</div>\n"
